function invalidParams(message) {
  const err = new Error(message);
  err.code = -32602;
  return err;
}

function assertNonEmptyString(value, name) {
  if (typeof value !== 'string' || value.length === 0) {
    throw invalidParams(`${name} must be a non-empty string`);
  }
}

function assertString(value, name) {
  if (typeof value !== 'string') {
    throw invalidParams(`${name} must be a string`);
  }
}

function validateArgs(args, spec) {
  const allowed = Object.keys(spec);
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw invalidParams(`unexpected argument: ${key}`);
    }
  }
  const cleaned = {};
  for (const key of allowed) {
    if (!(key in args)) {
      throw invalidParams(`missing argument: ${key}`);
    }
    spec[key](args[key], key);
    cleaned[key] = args[key];
  }
  return cleaned;
}
